import { useFormik } from 'formik';
import React, { useEffect, useState } from 'react'
import * as Yup from "yup";
import CreateSelect from "react-select/creatable";
import makeAnimated from "react-select/animated"
import { Button } from "@heroui/react";
import useApi from '../../hooks/useApi';
import paymentsApi from '../../api/paymentsApi';
import { useStateContext } from '../../contexts/ContextProvider';
import { PlusIcon } from '@radix-ui/react-icons';
import EntityPlanModal from './EntityPlanModal';
import EntityCollectionAccountModal from './EntityCollectionAccountModal';
import { List, Typography } from "antd";

export default function EntityPaymentSettings({ entity }) {
  const animatedComponent = makeAnimated();

  const [collectionAccounts, setcollectionAccounts] = useState();
  const { currentColor } = useStateContext();
  const [openEntityPlanModal, setopenEntityPlanModal] = useState(false);
  const [openCollectionAccountModal, setopenCollectionAccountModal] =
    useState(false);

  //Retrieve collection accounts
  const collectionAccountsActionsApi = useApi(paymentsApi.adminPaymentsAction);
  const getCollectionAccounts = async () => {
    await collectionAccountsActionsApi.request({
      action: "GetEntityPSPCollectionAccountsById",
      entity: entity.id,
    });
  };

  useEffect(() => {
    getCollectionAccounts();
  }, []);

  useEffect(() => {
    if (
      collectionAccountsActionsApi.data &&
      collectionAccountsActionsApi.data.length
    ) {
      setcollectionAccounts(collectionAccountsActionsApi.data);
    }
    console.log(
      "collectionAccountsActionsApi.data",
      collectionAccountsActionsApi.data
    );
  }, [collectionAccountsActionsApi.data]);

  const toggleEntityPlanModal = () => {
    setopenEntityPlanModal(!openEntityPlanModal);
  };

  const toggleCollectionAccountModal = () => {
    setopenCollectionAccountModal(!openCollectionAccountModal);
  };
  return (
    <div className="grid grid-cols-1  lg:grid-cols-2">
      <div className="p-3">
        <div
          style={{ background: currentColor }}
          className="flex justify-between items-center "
        >
          <p className="font-bold text-md text-white">Subscription Plan</p>
          <Button
            style={{ background: currentColor }}
            onClick={toggleEntityPlanModal}
            className="bg-transparent rounded text-white"
            endContent={<PlusIcon />}
            size="lg"
          >
            Select Plan
          </Button>
        </div>
        <div className="my-2">
          {entity.plan ? <p>{entity.plan_title}</p> : <p>No plan is set</p>}
        </div>
        <EntityPlanModal
          openEntityPlanModal={openEntityPlanModal}
          setopenEntityPlanModal={setopenEntityPlanModal}
          entity={entity}
        />
        <EntityCollectionAccountModal
          openCollectionAccountModal={openCollectionAccountModal}
          setopenCollectionAccountModal={setopenCollectionAccountModal}
          entity={entity}
        />
        <hr className="w-full mt-2" />
      </div>

      <div className="p-3">
        <div
          style={{ background: currentColor }}
          className="flex justify-between items-center "
        >
          <div className="p-2 font-medium text-lg">
            <p className="font-medium text-lg text-white">
              Payments Collection Accounts
            </p>
          </div>

          <Button
            style={{ background: currentColor }}
            onClick={toggleCollectionAccountModal}
            className="bg-transparent rounded text-white"
            endContent={<PlusIcon />}
            size="lg"
          >
            Add Account
          </Button>
        </div>
        {collectionAccounts && collectionAccounts.length ? (
          <div>
            <List
              header={
                <div>
                  <p>Active collection accounts: {collectionAccounts.length}</p>
                </div>
              }
              footer={<div>Footer</div>}
              bordered
              dataSource={collectionAccounts}
              renderItem={(item) => (
                <List.Item>
                  <Typography.Text mark>
                    {item.entity_account_number}
                  </Typography.Text>{" "}
                  {item.entity_account_name}
                </List.Item>
              )}
            />
          </div>
        ) : (
          <p>No collection accounts</p>
        )}
      </div>
    </div>
  );
}
