import { Tab, Tabs } from "@heroui/react"
import React from 'react'
import EntityEmployees from './EntityEmployees';
import EntityInventory from './EntityInventory';
import EntityInfo from './EntityInfo';
import EntityPlan from './EntityPlan';
import EntityPaymentSettings from './EntityPaymentsSettings';



function EntityDetailsTabs({ entity }) {

    let tabs = [
      {
        id: "about",
        label: "About",
        content: <EntityInfo entity={entity} />,
      },
      {
        id: "inventory",
        label: "Inventory",
        content: <EntityInventory />,
      },
      {
        id: "employees",
        label: "Employees",
        content: <EntityEmployees entity={entity} />,
      },
      {
        id: "payments",
        label: "Payment Services",
        content: <EntityPaymentSettings entity={entity} />,
      },
      {
        id: "plan",
        label: "Subscription Plan",
        content: <EntityPlan entity={entity} />,
      },
    ];
    return (
        <div className="flex w-full flex-col">
            <Tabs aria-label="Dynamic tabs" items={tabs} size='lg'>
                {(item) => (
                    <Tab key={item.id} title={item.label}>
                        <div className='w-full'> {item.content}</div>
                    </Tab>
                )}
            </Tabs>
        </div>
    )
}

export default EntityDetailsTabs