import React, { useEffect, useState } from "react";
import * as Yup from "yup";
import { Modal, ModalContent, ModalHeader, ModalBody, ModalFooter, Button, useDisclosure, Checkbox, Input, Link, Textarea, Select, SelectItem } from "@heroui/react";
import { FileUploader, Loading } from '../../components';
import { useFormik } from "formik";
import { ToastContainer, toast } from "react-toastify";

import { useDispatch, useSelector } from "react-redux";
import { resetRedux, uploadUserImages } from "../../redux/users/users/actions";
import { getLoggedInUser } from "../../helpers/authUtils";
import useApi from "../../hooks/useApi";
import kycDocumentsApi from "../../api/users/kycDocumentsApi";
import entitiesApi from "../../api/entitiesApi";
import { useNavigate } from "react-router-dom";



export default function ViewLicenceModal({ openModal, setopenModal, item, updated, setUpdated, modalTitle, selectedLicence }) {

    const [user, setUser] = useState()
    useEffect(() => { setUser(getLoggedInUser()) }, [])
    const navigate = useNavigate()

    console.log('selectedLicence', selectedLicence)

    const [errors, setErrors] = useState()

    useEffect(() => { setUser(getLoggedInUser()) }, [])

    const entitiesActionsApi = useApi(entitiesApi.entitiesAction)

    const handleDeleteLicence = async (doc) => {
        const result = await entitiesActionsApi.request({
            "action": "DeleteEntityLicence",
            "licence_details": {
                "licence": doc.id

            }
        })

        if (result.ok) {
            setopenModal(false)
        } else {
            console.log('res', result.data)
        }
    }
    const handleVerifyDocument = async (doc) => {
        console.log('doc', doc)

        const result = await entitiesActionsApi.request({
            "action": "VerifyEntityLicence",
            "licence_details": {
                "licence": doc.id,

            }
        })

        if (result.ok) {
            setopenModal(false)
            // navigate("/entities")
            toast.success("Document verified")

            console.log('result', result)
        } else {
            setErrors(result.data.errors)
            console.log('res', result.data)
            toast.error("Document not verified")
        }
    }

    useEffect(() => {
        if (errors && errors.length) {
            errors.map((x) => {
                toast.error(x);
            });
        }
    }, [errors]);
    return (
      <>
        <Modal
          isOpen={openModal}
          placement="center"
          size="lg"
          onClose={() => setopenModal(false)}
        >
          <ModalContent>
            <ToastContainer position="bottom-center" theme="colored" />
            <ModalHeader className="flex flex-col gap-1 items-center">
              KYC Document Details
            </ModalHeader>
            <ModalBody>
              <img
                src={selectedLicence.licence}
                className="h-1/4 w-full hover:shadow-lg"
                alt=""
              />

              <p className="font-bold">
                Document #: {selectedLicence.document_number}
              </p>

              <p
                className="uppercase
                        "
              >
                IS VERIFIED: {selectedLicence.is_verified}
              </p>
            </ModalBody>
            <ModalFooter>
              {selectedLicence.is_verified === "false" && (
                <Button
                  color="danger"
                  variant="light"
                  onPress={() => handleDeleteLicence(selectedLicence)}
                >
                  Delete
                </Button>
              )}
              {user &&
                user.is_staff === "true" &&
                selectedLicence.is_verified === "false" && (
                  <Button
                    color="primary"
                    onPress={() => handleVerifyDocument(selectedLicence)}
                  >
                    Verify
                  </Button>
                )}
            </ModalFooter>
          </ModalContent>
        </Modal>
      </>
    );
}
