import React, { useEffect, useState } from 'react'
import { TextItemLabelled } from '../../components'
import { Button, Divider } from "@heroui/react"
import ViewLicenceModal from './ViewLicenceModal'
import { getLoggedInUser } from '../../helpers/authUtils'
import useApi from '../../hooks/useApi'
import { entitiesAction } from '../../redux/users/entities/actions'
import entitiesApi from '../../api/entitiesApi'
import VerifyEntityModal from './VerifyEntityModal'

function EntityInfo({ entity }) {
    console.log('Entity', entity)

    const [openViewLicenceModal, setopenViewLicenceModal] = useState(false)
    const [openVerifyEntityModal, setopenVerifyEntityModal] = useState(false)
    const [selectedLicence, setselectedLicence] = useState()

    const [user, setUser] = useState()

    const handleSelectDocument = (licence) => {
        setopenViewLicenceModal(true)
        setselectedLicence(licence)
    }

    useEffect(() => {
        setUser(getLoggedInUser())
    }, [])
    console.log('User', user)

    const verifyEntityApi = useApi(entitiesApi.entitiesActionAdmin)

    const handleVerifyEntity = () => {
        setopenVerifyEntityModal(true)
    }
    return (
      <div>
        {user && user.is_staff === "false" && (
          <TextItemLabelled label="Is Verified" value={entity.is_verified} />
        )}
        {user && user.is_staff === "true" && (
          <div className="space-y-3">
            <h4 className="text-medium font-medium ">Verified</h4>
            {entity.is_verified == "true" ? (
              <p className="text-small uppercase text-default-400">
                {entity.is_verified}
              </p>
            ) : (
              <Button onPress={handleVerifyEntity} color="primary">
                Verify
              </Button>
            )}
            <Divider className="mt-5" />
          </div>
        )}

        <TextItemLabelled label="Date Created" value={entity.created} />

        <div className="space-y-3">
          <h4 className="text-medium font-medium ">Entity Licences</h4>
          {entity.licences && entity.licences.length ? (
            <div className=" grid grid-cols-4">
              {entity.licences.map((x) => (
                <div className="mb-4">
                  <img
                    onClick={() => handleSelectDocument(x)}
                    style={{ width: 60 }}
                    src={x.licence}
                    className="h-auto min-w-sm w-4 rounded-lg hover:shadow-2xl shadow-gray-700 hover:cursor-pointer"
                    alt=""
                  />
                </div>
              ))}
            </div>
          ) : (
            <p className="text-small text-default-400"> No licences uploaded</p>
          )}
          {/* <Button color='primary' onPress={() => setopenUploadDocumentModal(true)}>Upload licences</Button> */}
          <Divider className="mt-5" />

          {openViewLicenceModal && (
            <ViewLicenceModal
              openModal={openViewLicenceModal}
              setopenModal={setopenViewLicenceModal}
              selectedLicence={selectedLicence}
            />
          )}
          {openVerifyEntityModal && (
            <VerifyEntityModal
              openModal={openVerifyEntityModal}
              setopenModal={setopenVerifyEntityModal}
              entity={entity}
            />
          )}
        </div>
      </div>
    );
}

export default EntityInfo