import React, { useEffect, useState } from "react";
import * as Yup from "yup";
import { Modal, ModalContent, ModalHeader, ModalBody, ModalFooter, Button, useDisclosure, Checkbox, Input, Link, Textarea, Select, SelectItem } from "@heroui/react";
import { FileUploader, Loading } from '../../components';
import { useFormik } from "formik";
import { ToastContainer, toast } from "react-toastify";
import CreateSelect from "react-select/creatable";
import makeAnimated from "react-select/animated"
import { useDispatch, useSelector } from "react-redux";
import { resetRedux, uploadUserImages } from "../../redux/users/users/actions";
import { getLoggedInUser } from "../../helpers/authUtils";
import useApi from "../../hooks/useApi";
import categoriesApi from "../../api/categoriesApi";
import entitiesApi from "../../api/entitiesApi";
import { useNavigate } from "react-router-dom";



export default function VerifyEntityModal({ openModal, setopenModal, entity }) {
    const animatedComponent = makeAnimated();
    const loading = useSelector((state) => state.Users.loading);
    const response_code = useSelector((state) => state.Users.response_code);
    const response_message = useSelector((state) => state.Users.response_message);

    const [user, setUser] = useState()
    const dispatch = useDispatch()
    const [errors, setErrors] = useState([])

    const navigate = useNavigate()

    //Retrieve categories
    const [categories, setCategories] = useState([])
    const categoriesActionsApi = useApi(categoriesApi.categoriesAction

    )
    const getCategories = async () => {
        await categoriesActionsApi.request({
            "action": "GetAllCategories"

        })
    }

    useEffect(() => {
        getCategories()
    }, [])


    useEffect(() => {

        if (categoriesActionsApi.data && categoriesActionsApi.data.length) {

            setCategories(categoriesActionsApi.data.map((i) => ({ label: i.title, value: i.id })))
        }

        console.log
            ('countriesActionsApi.data', categoriesActionsApi.data)
    }, [categoriesActionsApi.data])

    useEffect(() => { setUser(getLoggedInUser()) }, [])


    const entitiesActionApi = useApi(entitiesApi.entitiesActionAdmin)

    const verifyEntity = async (data) => {
        const result = await entitiesActionApi.request(data)

        if (result.ok) {
            // navigate("/entities/all")
            toast.success("Entity succesfuly verified")
        } else {
            setErrors(result.data.errors)
            toast.error("Entity verification failed")
        }
    }



    const formik = useFormik({
        initialValues: {
            categories: [],
        },

        validationSchema: Yup.object({

            categories: Yup.array().min(1, 'Add at least one category to entity').label('Categories'),
        }),
        onSubmit: (values, { resetForm }) => {
            //Dispatch action

            console.log('VALZ', values)
            let arr = [];
            if (values.categories && values.categories.length) {
                values.categories.map((x) => {
                    arr.push(x.value);
                });
            }

            const data = {
                "action": "VerifyEntity",
                "entity": entity.id,
                "categories": arr

            }

            verifyEntity(data)

        },
    });


    useEffect(() => {
        if (errors && errors.length) {
            errors.map((x) => {
                toast.error(x);
            });
        }
    }, [errors]);

    useEffect(() => {
        if (response_message) {
            toast.success(response_message
            );
        }
    }, [response_message]);



    return (
        <>
            <Modal
                isOpen={openModal}
                placement="center"
            >
                <ModalContent>


                    {(onClose) => (
                        <>
                            <ToastContainer position="bottom-center" theme="colored" />

                            {loading ? <Loading /> : <form className="items-center grid grid-cols-1"
                                onSubmit={formik.handleSubmit}
                            > <ModalHeader className="flex flex-col gap-1 items-center">{entity.title}</ModalHeader>
                                <ModalBody className="items-center">Verify Now</ModalBody>
                                <ModalBody>


                                    <div>
                                        <CreateSelect
                                            styles={{
                                                control: (baseStyles, state) => ({
                                                    ...baseStyles,
                                                    borderColor: state.isFocused ? 'black' : 'grey',
                                                    height: '56px',
                                                    borderRadius: '20px',
                                                }),
                                            }}
                                            id="categories"
                                            key="categories"
                                            name="categories"
                                            components={animatedComponent}
                                            isMulti
                                            placeholder="Select entity categories"
                                            isClearable
                                            value={formik.values.categories}
                                            onChange={(value) => formik.setFieldValue("categories", value)}
                                            options={categories}
                                        />
                                        {formik.touched.categories && formik.errors.categories ? (
                                            <p className="text-red-400 text-sm">{formik.errors.categories}</p>
                                        ) : null}
                                    </div>




                                </ModalBody>
                                <ModalFooter>
                                    <Button color="danger" variant="flat" onPress={() => setopenModal(false)}>
                                        Cancel
                                    </Button>
                                    <Button color="primary" type="submit" onPress={onClose}>
                                        Save
                                    </Button>
                                </ModalFooter>

                            </form>}


                        </>
                    )}
                </ModalContent>
            </Modal>
        </>
    );
}
