import React, { useCallback, useEffect, useState } from "react";
import * as Yup from "yup";
import { Button } from "@heroui/react";
import {
  CustomDatePicker,
  CustomForm,
  CustomFormItem,
  CustomInput,
  CustomSelectReactSelect,
  CustomSwitch,
  CustomTimePicker,
  Loading,
} from "../../components";
import { useFormik } from "formik";
import useApi from "../../hooks/useApi";
import { ToastContainer, toast } from "react-toastify";
import transportApi from "../../api/transport/transportApi";

import usersApi from "../../api/usersApi";
import employeesApi from "../../api/employees/employeesApi";
import { Modal } from "antd";
import dayjs from "dayjs";

export default function EmployeeFormModal({
  ismodalOpen,
  setisModalOpen,
  employee,
  modalTitle = "Add new employee",
  updated,
  setUpdated,
  entity,
}) {
  console.log("employee at modal", employee);
  console.log("isModalOpen", ismodalOpen);

  const [crew, setCrew] = useState(
    employee && employee.crew_array
      ? employee.crew_array.map((i) => ({ label: i.title, value: i.id }))
      : []
  );

  const employeesActionsApi = useApi(employeesApi.employeesActionAdmin);
  const getEntityEmployees = async () => {
    await employeesActionsApi.request({
      action: "RetrieveEntityEmployees",
    });
  };

  useEffect(() => {
    getEntityEmployees();
  }, []);

  useEffect(() => {
    if (employeesActionsApi.data && employeesActionsApi.data.length) {
      setCrew(
        employeesActionsApi.data.map((i) => ({ label: i.title, value: i.id }))
      );
    }

    console.log("employeesActionsApi.data", employeesActionsApi.data);
  }, [employeesActionsApi.data]);

  const employeeActionsApi = useApi(employeesApi.employeesActionAdmin);

  const [errors, setErrors] = useState();

  const handleEmployeeAction = async (data) => {
    console.log("data at", data);
    const result = await employeeActionsApi.request(data);

    // if (result.ok) {
    //   console.log("res", result);
    //   setUpdated(true);
    //   setisModalOpen(false);
    // } else {
    //   setUpdated(false);
    // }
  };

  useEffect(() => {}, [employee]);

  useEffect(() => {
    if (employeeActionsApi.data) {
      // setisModalOpen(false);
      // if (transportActionsApi.data.destination) {
      //     setDestination(transportActionsApi.data.destination)
      // }

      if (
        employeeActionsApi.data.errors &&
        employeeActionsApi.data.errors.length
      ) {
        setErrors(employeeActionsApi.data.errors);
      }
    }

    console.log("transportActionsApi.data", employeeActionsApi.data);
  }, [employeeActionsApi.data]);

  const entityEntityUsersApi = useApi(usersApi.usersAction);

  const [entityUsers, setEntityUsers] = useState([]);
  const getEntityUsers = async () => {
    await entityEntityUsersApi.request({
      action: "GetEntityUsersById",
      entity: entity.id,
    });
  };

  useEffect(() => {
    if (entityEntityUsersApi.data && entityEntityUsersApi.data.length) {
      setEntityUsers(
        entityEntityUsersApi.data.map((i) => ({
          label: i.title,
          value: i.id,
        }))
      );
    }

    if (
      entityEntityUsersApi.data &&
      entityEntityUsersApi.data.response_message &&
      entityEntityUsersApi.data.response_code === 1
    ) {
      toast.error(entityEntityUsersApi.data.response_message);
    }

    if (
      entityEntityUsersApi.data &&
      entityEntityUsersApi.data.response_message &&
      entityEntityUsersApi.data.response_code === 0
    ) {
      toast.success(entityEntityUsersApi.data.response_message);
    }

    console.log("entityEntityUsersApi.data", entityEntityUsersApi.data);
  }, [entityEntityUsersApi.data]);

  useEffect(() => {
    if (errors && errors.length) {
      errors.map((x) => {
        toast.error(x);
      });
    }
  }, [errors]);

  useEffect(() => {
    getEntityUsers();
  }, []);

  const formik = useFormik({
    initialValues: {
      user: employee
        ? {
            value: employee.user,
            label: `${employee.first_name} ${employee.last_name}`,
          }
        : "",

      is_active: employee ? employee.is_active : "",
      hire_date: employee ? dayjs(employee.hire_date, "YYYY-MM-DD") : "",
      terminal_date: employee
        ? dayjs(employee.terminal_date, "YYYY-MM-DD")
        : "",
    },

    validationSchema: Yup.object({}),
    onSubmit: (values, { resetForm }) => {
      //Dispatch action

      console.log("VALZ", values);
      setErrors([]);

      let crewArr = [];
      if (values.crew && values.crew.length) {
        values.crew.map((x) => {
          crewArr.push(x.value);
        });
      }

      let routesArr = [];
      if (values.crew && values.routes.length) {
        values.routes.map((x) => {
          routesArr.push(x.value);
        });
      }

      let saccoSubscriptionsArr = [];
      if (values.sacco_subscriptions && values.sacco_subscriptions.length) {
        values.sacco_subscriptions.map((x) => {
          saccoSubscriptionsArr.push(x.value);
        });
      }

      if (employee) {
        handleEmployeeAction({
          action: "UpdateCorporateEmployee",
          employee_details: {
            employee: employee.id,
            is_active: values.is_active,
            terminal_date: values.terminal_date,
            hire_date: values.hire_date,
            user: values.user.value,
          },
        });
      } else {
        handleEmployeeAction({
          action: "CreateCorporateEmployee",
          employee_details: {
            is_active: values.is_active,
            terminal_date: values.terminal_date,
            hire_date: values.hire_date,
            user: values.user.value,
            entity: entity.id,
          },
        });
      }

      // resetForm();
    },
  });

  const handleOk = () => {
    setisModalOpen(false);
  };
  const handleCancel = () => {
    setisModalOpen(false);
  };

  const [switchLabel, setswitchLabel] = useState("Activate");
  const handleSwitchChange = (checked) => {
    console.log("Swict", checked);
    formik.setFieldValue("is_active", checked ? "true" : "false");
    setswitchLabel(checked ? "Deactivate" : "Activate");
  };

  const handleHireDateChange = (date, dateString) => {
    formik.setFieldValue("hire_date", dateString);
  };

  const handleTerminalDateChange = (date, dateString) => {
    formik.setFieldValue("terminal_date", dateString);
  };

  return (
    <div className="w-full">
      <Modal
        width={540}
        className="w-full text-center"
        title={modalTitle}
        open={ismodalOpen}
        onOk={handleOk}
        onCancel={handleCancel}
        cancelButtonProps={{ style: { display: "none" } }}
        okButtonProps={{ style: { display: "none" } }}
      >
        <ToastContainer theme="colored" position="bottom-center" />

        {errors && errors.length ? (
          <div>
            {errors.map((error) => {
              <p className="text-red-500 text-2xl">{error}</p>;
            })}
          </div>
        ) : (
          <div></div>
        )}

        <CustomForm
          layout="vertical"
          handleFinish={formik.handleSubmit}
          className=" flex flex-col justify-center items-center w-full my-7"
        >
          <CustomFormItem
            touched={formik.touched.user}
            error={formik.errors.user}
          >
            <CustomSelectReactSelect
              className="text-start"
              name="user"
              id="user"
              label="Select user"
              size="large"
              onChange={(value) => formik.setFieldValue("user", value)}
              value={formik.values.user}
              placeholder="Select user"
              options={entityUsers}
            />
          </CustomFormItem>

          <CustomFormItem
            touched={formik.touched.hire_date}
            error={formik.errors.hire_date}
          >
            <CustomDatePicker
              id="hire_date"
              name="hire_date"
              size="large"
              placeholder="Select hire date"
              defaultValue={formik.values.hire_date}
              onChange={handleHireDateChange}
            />
          </CustomFormItem>

          <CustomFormItem
            touched={formik.touched.terminal_date}
            error={formik.errors.terminal_date}
          >
            <CustomDatePicker
              id="terminal_date"
              name="terminal_date"
              size="large"
              defaultValue={formik.values.terminal_date}
              placeholder="Select retire date"
              onChange={handleTerminalDateChange}
            />
          </CustomFormItem>

          <CustomFormItem
            touched={formik.touched.is_active}
            error={formik.errors.is_active}
          >
            <CustomSwitch
              id="is_active"
              checked={formik.values.is_active === "true"}
              onChange={(e) => handleSwitchChange(e)}
              title={switchLabel}
              checkedChildren="Deactivate"
              unCheckedChildren="Activate"
              label="Status: "
            />
          </CustomFormItem>

          <div className="w-full items-center mt-2">
            <Button className="w-36 rounded-md" color="primary" type="submit">
              Submit
            </Button>
          </div>
        </CustomForm>
      </Modal>
    </div>
  );
}
