import React, { useEffect, useState } from "react";
import { ConfirmDialog, MiniTable } from "../../components";
import useApi from "../../hooks/useApi";
import employeesApi from "../../api/employees/employeesApi";

import entitiesApi from "../../api/entitiesApi";
import { Button } from "antd";
import { useStateContext } from "../../contexts/ContextProvider";
import EmployeeFormModal from "./EmployeeFormModal";

function EntityEmployees({ entity }) {
  const { currentColor } = useStateContext();
  console.log("ent", entity);
  const entityEmployeesApi = useApi(employeesApi.employeesActionAdmin);
  const [entityUsers, setentityUsers] = useState([]);
  const getEntityUsers = async () => {
    await entityEmployeesApi.request({
      action: "RetrieveEntityEmployeesById",
      entity: entity.id,
    });
  };

  useEffect(() => {
    if (entity) {
      getEntityUsers(entity);
    }
  }, [entity]);

  useEffect(() => {
    if (entityEmployeesApi.data && entityEmployeesApi.data.length) {
      setentityUsers(entityEmployeesApi.data);
    }
    console.log("entityEmployeesApi.data", entityEmployeesApi.data);
  }, [entityEmployeesApi.data]);
  const [openConfirmDialog, setopenConfirmDialog] = useState(false);
  const [selectedEmployee, setselectedEmployee] = useState();

  const updateEntityAdminApi = useApi(entitiesApi.entitiesActionAdmin);
  const updateEntityAdministrator = async (selectedEmployee) => {
    await updateEntityAdminApi.request({
      action: "UpdateEntityAdministrator",
      entity: entity.id,
      employee: selectedEmployee.id,
    });
  };

  const handleOkSelected = () => {
    console.log("Selected employee", selectedEmployee);
    if (selectedEmployee) {
      updateEntityAdministrator(selectedEmployee);
    }
  };

  const [errors, setErrors] = useState([]);
  useEffect(() => {
    console.log("updateEntityAdminApi.data", updateEntityAdminApi.data);
    if (updateEntityAdminApi.data) {
      if (
        updateEntityAdminApi.data.errors &&
        updateEntityAdminApi.data.errors.length
      ) {
        setErrors(updateEntityAdminApi.data.errors);
      }
    }
  }, [updateEntityAdminApi.data]);

  const [showdialogEmployeeForm, setshowdialogEmployeeForm] = useState(false);
  const [updated, setUpdated] = useState(false);

  return (
    <div>
      {errors && errors.length ? (
        <div className="h-10 bg-gray-50">
          {errors.map((error) => {
            return <p className="text-red-500 text-xl">{error}</p>;
          })}
        </div>
      ) : (
        <div></div>
      )}
      <div className="flex justify-between items-center my-2 py-2">
        <p>{entityUsers.length} employees</p>
        <Button
          onClick={() => setshowdialogEmployeeForm(!showdialogEmployeeForm)}
          className="text-white"
          style={{ backgroundColor: currentColor, textEmphasisColor: "white" }}
        >
          Add New
        </Button>
      </div>
      <EmployeeFormModal
        ismodalOpen={showdialogEmployeeForm}
        setisModalOpen={setshowdialogEmployeeForm}
        modalTitle="Add New Employee"
        entity={entity}
        updated={updated}
        setUpdated={setUpdated}
      />
      {selectedEmployee && (
        <ConfirmDialog
          open={openConfirmDialog}
          setOpen={setopenConfirmDialog}
          handleOkSelected={() => handleOkSelected()}
          selectedEmployee={selectedEmployee}
          setselectedEmployee={setselectedEmployee}
        />
      )}
      <MiniTable
        entityUsers={entityUsers}
        openConfirmDialog={openConfirmDialog}
        setopenConfirmDialog={setopenConfirmDialog}
        selectedEmployee={selectedEmployee}
        setselectedEmployee={setselectedEmployee}
      />
    </div>
  );
}

export default EntityEmployees;
